var i=`0249-galaktoboureko`;var n=`world-0249`;var a=`GR`;var o=`southern-europe`;var r=8;var l=73;var s={en:`Galaktoboureko`,ua:`Галактобуреко`};var u={en:`A traditional Greece dish made with whole cow milk, semolina flour, chicken egg, phyllo pastry. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Греція. Основні інгредієнти: цільне коров'яче молоко, семоліна, куряче яйце, тісто філо. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var g=[{en:`Cook the listed ingredients in simmering water for about 9 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 9 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:9,i:[[`whole-cow-milk`,850,`ml`],[`semolina-flour`,160,`g`],[`white-granulated-sugar`,140,`g`],[`unsalted-butter`,60,`g`],[`vanilla-extract`,4,`ml`]]},{en:`Gently fold in the remaining dry or wet ingredients just until homogeneous, without deflating the mixture.`,ua:`Обережно вмішайте решту сухих або рідких складників лише до однорідності, не осаджуючи масу.`,t:[`folding-batter`],m:4,i:[[`chicken-egg`,3,`pcs`]]},{en:`Layer the prepared elements evenly in the baking dish, spreading filling right to the edges.`,ua:`Викладіть підготовлені компоненти рівними шарами у формі, розподіляючи начинку до країв.`,t:[`layered-assembly`],m:12,i:[[`phyllo-pastry`,300,`g`],[`unsalted-butter`,95,`g`]]},{en:`Bake in a preheated 180°C oven for about 40 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 40 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:40,i:[]},{en:`Boil sugar, water and lemon into a light syrup; pour cooled syrup over the hot baked galaktoboureko so the phyllo remains crisp.`,ua:`Зваріть із цукру, води й лимону легкий сироп; полийте охолодженим сиропом гаряче галактобуреко, щоб філо залишилося хрустким.`,t:[`reducing-sauce`],m:8,i:[[`water`,180,`ml`],[`white-granulated-sugar`,150,`g`],[`lemon-juice`,25,`ml`]]}];var d={slug:i,id:n,country:`GR`,region:o,servings:8,minutes:73,title:s,text:u,steps:g};export{a as country,d as default,n as id,l as minutes,o as region,r as servings,i as slug,g as steps,u as text,s as title};